values ('10000000-0000-4000-8000-000000000015'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Gumbo poulet-andouille de La Nouvelle-Orléans','gumbo-poulet-andouille-new-orleans','Gumbo louisianais au roux foncé avec poulet, saucisse andouille, poivron, céleri et oignon, servi avec riz blanc et herbes.','Ragoût louisianais au roux foncé, poulet et andouille.','fr','US','La Nouvelle-Orléans, Louisiane','Ragoût','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,35,150,8.00,now(),(select id from public.culinary_places where slug='us-new-orleans'),true,'Wikibooks Cookbook','https://en.wikibooks.org/wiki/Cookbook:Chicken_and_Andouille_Sausage_Gumbo','Version éditoriale réécrite. Le riz et les herbes de finition correspondent à la présentation de la photo prise à La Nouvelle-Orléans.')
