values ('10000000-0000-4000-8000-000000000016'::uuid,'ac515660-4852-4ebd-8cb5-3348d60e06e9'::uuid,'Riz au poulet hainanais de Singapour','riz-poulet-hainanais-singapour','Poulet délicatement poché, riz parfumé cuit au bouillon, concombre, légumes verts, échalotes frites et sauces d’accompagnement.','Poulet poché tendre avec riz au bouillon parfumé.','fr','SG','Singapour','Poulet et riz','adapted'::public.recipe_authenticity,'published'::public.recipe_status,'hard'::public.recipe_difficulty,35,70,6.00,now(),(select id from public.culinary_places where slug='sg-singapore-city'),true,'Wikibooks Cookbook','https://en.wikibooks.org/wiki/Cookbook:Hainanese_Chicken_Rice','Version éditoriale complétée pour correspondre à la photo prise à Singapour; elle inclut légumes verts, échalotes frites et un petit bouillon de service.')
