insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000006'::uuid,0,'Couper les pommes de terre en frites épaisses, les rincer à l’eau froide puis les sécher complètement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000006'::uuid,1,'Chauffer l’huile à environ 160 °C. Cuire les frites 5 à 6 minutes sans trop les colorer, puis les égoutter et les laisser reposer 10 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000006'::uuid,2,'Pour la sauce, faire fondre le beurre, ajouter la farine et cuire 2 minutes en remuant. Incorporer graduellement le bouillon et la sauce Worcestershire. Laisser mijoter jusqu’à épaississement, puis poivrer et saler au goût.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000006'::uuid,3,'Monter l’huile à environ 190 °C et frire une seconde fois les pommes de terre jusqu’à ce qu’elles soient dorées et croustillantes. Bien égoutter.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000006'::uuid,4,'Déposer les frites dans un plat, répartir immédiatement le fromage en grains puis napper de sauce brune très chaude. Servir tout de suite.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000007'::uuid,0,'Tapisser un moule carré d’environ 20 cm de papier cuisson.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000007'::uuid,1,'Faire fondre 125 g de beurre avec le sucre et le cacao à feu doux. Incorporer l’œuf battu en remuant constamment jusqu’à léger épaississement, sans laisser brouiller.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000007'::uuid,2,'Retirer du feu et incorporer les miettes Graham, les amandes et la noix de coco. Presser fermement au fond du moule puis réfrigérer.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000007'::uuid,3,'Battre 115 g de beurre avec la crème et la poudre à pouding. Ajouter progressivement le sucre à glacer et battre jusqu’à texture légère. Étendre sur la base froide.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000007'::uuid,4,'Faire fondre le chocolat avec 30 g de beurre. Laisser tiédir puis étendre en une couche mince sur la crème.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000007'::uuid,5,'Réfrigérer jusqu’à ce que les trois couches soient fermes. Couper en 16 carrés avec un couteau légèrement chauffé.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,0,'Blanchir les os de bœuf 5 minutes dans l’eau bouillante, les rincer soigneusement puis nettoyer la marmite.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,1,'Couper les oignons et le gingembre en deux et les griller à sec jusqu’à ce que leurs faces soient bien brunies. Griller aussi brièvement anis, cannelle, girofle et coriandre.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,2,'Mettre les os, la pointe de poitrine, les aromates grillés et environ 3 litres d’eau dans la marmite. Porter juste à frémissement et écumer régulièrement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,3,'Après environ 90 minutes, retirer la poitrine lorsqu’elle est tendre. Continuer le bouillon encore 90 à 120 minutes, puis filtrer.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,4,'Assaisonner le bouillon avec sauce de poisson, sucre et sel. Il doit être parfumé, clair et légèrement plus salé que si on le buvait seul.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,5,'Cuire ou réhydrater les nouilles de riz selon leur emballage et les répartir dans les bols. Ajouter la poitrine tranchée et les fines tranches de bœuf cru.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000008'::uuid,6,'Verser le bouillon bouillant sur le bœuf. Garnir d’oignons verts et de coriandre. Servir avec quartiers de lime et piments rouges, comme sur la photo de Hanoï.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000009'::uuid,0,'Cuire le riz et le garder chaud. Mélanger le bœuf avec la moitié de la sauce soja, un peu d’huile de sésame, le sucre et l’ail.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000009'::uuid,1,'Blanchir séparément les épinards et les germes de soja. Égoutter soigneusement puis assaisonner chacun d’un peu d’huile de sésame, de sel et de graines de sésame.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000009'::uuid,2,'Sauter séparément carotte, courgette et shiitake avec très peu d’huile afin de conserver leurs couleurs et textures.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000009'::uuid,3,'Saisir le bœuf mariné à feu vif jusqu’à cuisson. Cuire les œufs sur le plat en gardant le jaune tendre.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000009'::uuid,4,'Répartir le riz dans trois grands bols. Disposer en sections le bœuf, carotte, courgette, épinards, germes, shiitake, concombre, hwangpomuk et pousses de radis.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000009'::uuid,5,'Déposer un œuf au centre. Ajouter gochujang, algue émincée et graines de sésame. Mélanger soigneusement juste avant de manger.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000010'::uuid,0,'Couper le poulet en gros morceaux. Mélanger yogourt, jus de citron, la moitié de l’ail et du gingembre, garam masala, cumin, paprika et curcuma. Mariner au moins 30 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000010'::uuid,1,'Saisir ou griller le poulet à feu élevé jusqu’à ce qu’il soit bien coloré. Il finira de cuire dans la sauce.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000010'::uuid,2,'Faire fondre la moitié du beurre. Ajouter le reste d’ail et de gingembre, cuire brièvement puis ajouter les tomates. Laisser réduire 15 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000010'::uuid,3,'Mixer la sauce pour une texture lisse si désiré, puis ajouter crème, sucre, sel et le reste du beurre.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000010'::uuid,4,'Ajouter le poulet et laisser mijoter doucement 10 à 12 minutes, jusqu’à cuisson complète.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000010'::uuid,5,'Garnir de coriandre fraîche et servir chaud.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000011'::uuid,0,'Saler légèrement le poulet et l’arroser du jus de la moitié du citron. Laisser reposer pendant la préparation des oignons.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000011'::uuid,1,'Cuire les oignons seuls dans une cocotte à feu moyen-doux 20 à 25 minutes en remuant, jusqu’à ce qu’ils soient très tendres et concentrés.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000011'::uuid,2,'Ajouter le niter kibbeh, le berbere, l’ail et le gingembre. Cuire 3 minutes jusqu’à ce que les épices soient très parfumées.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000011'::uuid,3,'Ajouter le poulet et l’enrober de la base épicée. Verser le bouillon et laisser mijoter à couvert environ 45 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000011'::uuid,4,'Inciser légèrement les œufs durs et les ajouter au ragoût. Poursuivre 15 minutes à découvert jusqu’à sauce épaisse. Ajuster sel et citron.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000011'::uuid,5,'Servir le doro wat avec injera et légumes verts cuits, en déposant un œuf dans chaque portion.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000012'::uuid,0,'Faire revenir l’oignon et les carottes dans un peu de matière grasse jusqu’à ce qu’ils commencent à ramollir.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000012'::uuid,1,'Ajouter les betteraves, l’ail et la pâte de tomate. Cuire 5 minutes en remuant.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000012'::uuid,2,'Verser le bouillon, ajouter les pommes de terre et porter à frémissement. Cuire environ 35 minutes, jusqu’à ce que tous les légumes soient tendres.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000012'::uuid,3,'Ajouter vinaigre, sucre, sel et poivre. Laisser mijoter encore 5 minutes puis rectifier l’acidité et l’assaisonnement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000012'::uuid,4,'Servir très chaud avec une cuillerée de crème sure, oignons verts émincés et persil plat. Mélanger la crème dans la soupe au moment de manger.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000013'::uuid,0,'Mélanger farine et sel. Ajouter l’œuf, l’eau graduellement et le beurre fondu. Pétrir jusqu’à obtenir une pâte lisse, puis couvrir et laisser reposer 30 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000013'::uuid,1,'Cuire les pommes de terre jusqu’à tendreté, les égoutter puis les écraser. Faire revenir les oignons hachés dans la moitié du beurre jusqu’à coloration légère.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000013'::uuid,2,'Mélanger pommes de terre, fromage et la moitié des oignons cuits. Saler et poivrer puis laisser refroidir.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000013'::uuid,3,'Abaisser la pâte finement et découper des disques d’environ 8 cm. Déposer une cuillerée de farce au centre, plier en demi-lune et pincer soigneusement les bords.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000013'::uuid,4,'Cuire les pierogi par petites quantités dans l’eau salée frémissante. Lorsqu’ils remontent, poursuivre 2 à 3 minutes puis égoutter.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000013'::uuid,5,'Faire revenir brièvement les pierogi dans le reste du beurre et servir avec les oignons cuits réservés.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000014'::uuid,0,'Cuire séparément les patates douces et le manioc jusqu’à tendreté. Cuire le choclo, puis laisser tous les accompagnements refroidir. Préparer la cancha grillée.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000014'::uuid,1,'Couper le poisson très froid en cubes d’environ 2 cm. Le garder sur glace ou au réfrigérateur jusqu’au dernier moment.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000014'::uuid,2,'Mélanger poisson, sel, piment haché, coriandre et une partie de l’oignon rouge. Ajouter le jus de lime et mélanger doucement.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000014'::uuid,3,'Laisser mariner seulement le temps nécessaire pour que la surface du poisson devienne opaque tout en gardant un centre tendre, environ 5 à 10 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000014'::uuid,4,'Dresser sur la laitue avec le reste d’oignon. Ajouter autour le choclo, manioc, cancha, patate douce et yuyo afin que l’assiette corresponde à la présentation traditionnelle photographiée à Callao.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000014'::uuid,5,'Servir immédiatement et garder le ceviche bien froid.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000015'::uuid,0,'Faire dorer les morceaux de poulet dans une cocotte avec un peu d’huile, puis réserver. Faire colorer aussi l’andouille et réserver.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000015'::uuid,1,'Ajouter l’huile restante puis la farine. Cuire le roux à feu moyen en remuant constamment jusqu’à une couleur brun chocolat, sans le brûler.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000015'::uuid,2,'Ajouter immédiatement oignon, poivron et céleri. Cuire 8 à 10 minutes, puis ajouter l’ail.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000015'::uuid,3,'Verser graduellement le bouillon en fouettant. Ajouter laurier, thym, Cayenne, poulet et andouille.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000015'::uuid,4,'Laisser frémir doucement 90 minutes à 2 heures en remuant de temps en temps. Dégraisser la surface au besoin et ajuster le sel.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000015'::uuid,5,'Servir dans des bols avec une portion de riz blanc. Finir avec oignons verts et persil frais.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000016'::uuid,0,'Frotter le poulet avec le sel puis le rincer. Porter une grande marmite d’eau à frémissement avec la moitié du gingembre, quatre gousses d’ail et trois oignons verts.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000016'::uuid,1,'Pocher le poulet à très petit frémissement jusqu’à cuisson complète, environ 40 à 45 minutes selon sa taille. Le transférer dans un bain d’eau glacée 10 minutes, puis égoutter.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000016'::uuid,2,'Pour le riz, faire revenir le gras de poulet avec le reste d’ail et de gingembre. Ajouter le riz rincé et remuer 2 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000016'::uuid,3,'Ajouter 650 ml de bouillon de cuisson et le pandan. Cuire le riz à couvert jusqu’à absorption.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000016'::uuid,4,'Blanchir les bok choy. Trancher le concombre et découper le poulet en morceaux.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000016'::uuid,5,'Servir le poulet avec le riz, concombre, légumes verts et échalotes frites. Présenter les sauces à part et un petit bol de bouillon clair chaud.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,0,'Mélanger eau tiède, sucre et levure. Laisser mousser 5 à 10 minutes.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,1,'Ajouter farine, sel et huile. Pétrir 8 à 10 minutes jusqu’à pâte souple. Couvrir et laisser lever environ 1 heure.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,2,'Râper ou émietter les deux fromages et les mélanger. Préchauffer le four à 240 °C avec une plaque épaisse à l’intérieur.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,3,'Diviser la pâte en quatre. Étaler chaque morceau en ovale, rouler les deux longs côtés vers le centre puis pincer les extrémités pour former un bateau.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,4,'Répartir généreusement le mélange de fromages au centre. Cuire 12 à 15 minutes jusqu’à ce que les bords soient bien dorés.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,5,'Sortir les pains, creuser légèrement le fromage au centre et casser un œuf dans chacun. Remettre au four 2 à 3 minutes : le blanc doit commencer à prendre mais le jaune rester coulant.',null,null);
insert into public.recipe_steps (recipe_id,position,instruction,timer_seconds,image_path) values ('10000000-0000-4000-8000-000000000017'::uuid,6,'Déposer immédiatement environ 15 g de beurre sur chaque khachapuri. Mélanger œuf, beurre et fromage au centre avant de déchirer les bords du pain pour les tremper.',null,null);
